import NxlvKit

/// Authored stories, never assembled from interchangeable fragments.
/// Version 2 is frozen: preserve its wording, indices and count for saved-run identity.
enum LemmingAssessmentCatalogue {
    static let version = 2
    static let count = 128

    static func index(seed: UInt64, actorID: Int) -> Int {
        // An odd stride visits every entry exactly once before repeating.
        // The mapping does not depend on the current number or order of actors.
        let offset = Int((seed >> 8) & 127)
        let stride = Int((seed >> 16) & 63) * 2 + 1
        return (offset + (actorID % count) * stride) % count
    }

    static func story(at index: Int) -> (String, String) {
        switch index {
        case 0: (L10n.text("Owns seven smooth stones."), L10n.text("One is reserved for overnight visitors."))
        case 1: (L10n.text("Enjoys the rain."), L10n.text("Has described indoor rain as largely unnecessary."))
        case 2: (L10n.text("Has seen the sea twice."), L10n.text("Recognised it the second time."))
        case 3: (L10n.text("Is welcome in three kitchens."), L10n.text("May sit down in two."))
        case 4: (L10n.text("Keeps string in a designated drawer."), L10n.text("No complaints were received."))
        case 5: (L10n.text("Owns an inland shell."), L10n.text("Accepts the shopkeeper's account without reservation."))
        case 6: (L10n.text("Is known to hum at home."), L10n.text("The tune remains unidentified."))
        case 7: (L10n.text("Has been consulted about moss."), L10n.text("Was given time to finish."))
        case 8: (L10n.text("Recognises four kinds of cloud."), L10n.text("Prefers the one from Tuesday."))
        case 9: (L10n.text("Uses a different spoon on Sundays."), L10n.text("The food remains unchanged."))
        case 10: (L10n.text("Received a leaf by post."), L10n.text("Still thinks about the gesture."))
        case 11: (L10n.text("Owns a shelf of adequate depth."), L10n.text("Its width was approved."))
        case 12: (L10n.text("Bought two cups after meeting someone."), L10n.text("Still uses them alternately."))
        case 13: (L10n.text("Keeps a birthday candle ready."), L10n.text("Nobody needs to know why."))
        case 14: (L10n.text("A neighbour remembers their favourite biscuit."), L10n.text("This has helped considerably."))
        case 15: (L10n.text("Has a photograph of an empty chair."), L10n.text("Remembers the afternoon."))
        case 16: (L10n.text("Learned to cook for someone."), L10n.text("Continues making the smaller portion."))
        case 17: (L10n.text("Has finally received an invitation."), L10n.text("Keeps checking the correct year."))
        case 18: (L10n.text("Once won a small raffle."), L10n.text("Still visits the winning towel."))
        case 19: (L10n.text("Their apology arrived before the argument."), L10n.text("Both parties felt prepared."))
        case 20: (L10n.text("Keeps the ugly vase."), L10n.text("Someone chose it with great care."))
        case 21: (L10n.text("Their window faces another window."), L10n.text("Occasionally both lamps stay on."))
        case 22: (L10n.text("Grew a tomato successfully."), L10n.text("Invited three people to witness lunch."))
        case 23: (L10n.text("Their last letter contains no news."), L10n.text("It was welcome anyway."))
        case 24: (L10n.text("Makes excellent soup for one."), L10n.text("Owns a reassuringly large ladle."))
        case 25: (L10n.text("Someone remembered their name today."), L10n.text("They had brought identification anyway."))
        case 26: (L10n.text("Has a coat for special occasions."), L10n.text("Wore it buying bread."))
        case 27: (L10n.text("Their garden contains one flower."), L10n.text("Visitors are shown it individually."))
        case 28: (L10n.text("Once received unexpected praise."), L10n.text("Can still recall the exact wording."))
        case 29: (L10n.text("Keeps a spare chair ready."), L10n.text("The cat understands the arrangement."))
        case 30: (L10n.text("Took the scenic route home."), L10n.text("Nothing especially scenic was required."))
        case 31: (L10n.text("Has stopped expecting a reply."), L10n.text("Still recognises the postman's footsteps."))
        case 32: (L10n.text("Their friend moved somewhere warmer."), L10n.text("The spare blanket remains folded."))
        case 33: (L10n.text("Enjoys being asked about the weather."), L10n.text("Prepares several possible answers."))
        case 34: (L10n.text("Knitted a scarf for someone taller."), L10n.text("It reached them eventually."))
        case 35: (L10n.text("Made a friend during a queue."), L10n.text("Sometimes misses the queue."))
        case 36: (L10n.text("Their houseplant has grown another leaf."), L10n.text("No announcement was necessary."))
        case 37: (L10n.text("Saved the last biscuit for later."), L10n.text("Later was unexpectedly pleasant."))
        case 38: (L10n.text("Has forgiven the broken teapot."), L10n.text("Keeps the handle somewhere safe."))
        case 39: (L10n.text("Their neighbour plays the same song."), L10n.text("It has become company."))
        case 40: (L10n.text("Has been described as dependable."), L10n.text("The reference concerned a kettle."))
        case 41: (L10n.text("Can distinguish three kinds of silence."), L10n.text("Recommends the one upstairs."))
        case 42: (L10n.text("Was authorised to choose a cushion."), L10n.text("The decision remains respected."))
        case 43: (L10n.text("Their handwriting improves on envelopes."), L10n.text("Nobody has formally requested this."))
