        case 52: (L10n.text("Their curtains are regarded as adequate."), L10n.text("They found this comforting."))
        case 53: (L10n.text("Is trusted with the larger scissors."), L10n.text("The responsibility feels manageable."))
        case 54: (L10n.text("Was thanked for noticing a draught."), L10n.text("Keeps the written confirmation."))
        case 55: (L10n.text("Their preferred bench faces a wall."), L10n.text("Finds the view reliable."))
        case 56: (L10n.text("Has an excellent memory for porridge."), L10n.text("Several breakfasts remain vivid."))
        case 57: (L10n.text("Is known to return borrowed containers."), L10n.text("Sometimes containing different things."))
        case 58: (L10n.text("Their opinion of pears is available."), L10n.text("No appointment is required."))
        case 59: (L10n.text("Owns a small decorative bell."), L10n.text("Its silence has been satisfactory."))
