        case 73: (L10n.text("Their first cake leaned considerably."), L10n.text("Nobody asked it to stand."))
        case 74: (L10n.text("Has a drawer for useful things."), L10n.text("Opens it for reassurance."))
        case 75: (L10n.text("Their painting resembles somewhere they miss."), L10n.text("The actual place disagrees."))
        case 76: (L10n.text("Has named the draught under the door."), L10n.text("Welcomes it politely."))
        case 77: (L10n.text("Their guest towel has hosted nobody."), L10n.text("Remains prepared without complaint."))
        case 78: (L10n.text("Made enough jam for the winter."), L10n.text("Summer visitors proved enthusiastic."))
        case 79: (L10n.text("Their shoes squeak in different keys."), L10n.text("Walks home with accompaniment."))
        case 80: (L10n.text("Has a tiny balcony."), L10n.text("The outside world makes regular appearances."))
        case 81: (L10n.text("Their favourite shop closed last spring."), L10n.text("Remembers where everything was."))
        case 82: (L10n.text("Keeps a shopping list from happier times."), L10n.text("Mostly ordinary groceries."))
        case 83: (L10n.text("Their old address appears on something."), L10n.text("Paused before correcting it."))
        case 84: (L10n.text("Has found a reason to celebrate."), L10n.text("Uses the everyday plates."))
        case 85: (L10n.text("Their new friend dislikes the same chair."), L10n.text("A promising beginning."))
        case 86: (L10n.text("Was invited back without asking."), L10n.text("The walk home felt shorter."))
        case 87: (L10n.text("Their neighbour left a light on."), L10n.text("It helped with something."))
        case 88: (L10n.text("Has learned the name of a bird."), L10n.text("Uses it privately."))
        case 89: (L10n.text("Their family recipe includes an unexplained pause."), L10n.text("Observes it faithfully."))
        case 90: (L10n.text("Owns a modest collection of keys."), L10n.text("Several doors remain hypothetical."))
        case 91: (L10n.text("Their surname was misspelled on an award."), L10n.text("Displays it anyway."))
        case 92: (L10n.text("Has kept one promise to themselves."), L10n.text("It concerned fresh sheets."))
        case 93: (L10n.text("Their favourite jumper has become a cushion."), L10n.text("Affection remains unchanged."))
