        case 126: (L10n.text("Has a favourite sound at home."), L10n.text("Someone putting water on."))
        case 127: (L10n.text("Their ordinary day went mostly as expected."), L10n.text("Would recommend another."))
        default: preconditionFailure("Unknown assessment index")
        }
    }
}
